    constexpr float k26 = 1.17647059e-01f;
    constexpr float k27 = 1.33333333e-01f;
    constexpr float k28 = 1.42857143e-01f;
    constexpr float k29 = 2.00000000e-01f;
    constexpr float k30 = 3.33333333e-01f;
    constexpr float k31 = 7.85398163e-01f;
    constexpr float k32 = 1.00000000e+00f;
    constexpr float k33 = 2.00000000e+00f;
    constexpr float k34 = 2.25675833e+00f;
    constexpr float k35 = 2.25675833e+00f;
    constexpr float k36 = 3.00000000e+00f;
