    output[4] *= broadcast<SimdVector<float, 8>>(
        kScaleFactorInverse1 * kScaleFactorInverse1 * kScaleFactorInverse1);
    output[5] *= broadcast<SimdVector<float, 8>>(
        kScaleFactorInverse1 * kScaleFactorInverse1 * kScaleFactorInverse1);
