    SimdVector<double, 4> const y = broadcast<SimdVector<double, 4>>(k37) * r2;
    SimdVector<double, 4> const exponential = detail::ewaldExp(-y);
    SimdVector<double, 4> series = one;
    series = fma(series, y * broadcast<SimdVector<double, 4>>(k01), one);
    series = fma(series, y * broadcast<SimdVector<double, 4>>(k02), one);
    series = fma(series, y * broadcast<SimdVector<double, 4>>(k03), one);
    series = fma(series, y * broadcast<SimdVector<double, 4>>(k04), one);
    series = fma(series, y * broadcast<SimdVector<double, 4>>(k05), one);
    series = fma(series, y * broadcast<SimdVector<double, 4>>(k06), one);
    series = fma(series, y * broadcast<SimdVector<double, 4>>(k07), one);
    series = fma(series, y * broadcast<SimdVector<double, 4>>(k08), one);
    series = fma(series, y * broadcast<SimdVector<double, 4>>(k09), one);
    series = fma(series, y * broadcast<SimdVector<double, 4>>(k10), one);
