    constexpr double k38 = 5.00000000000000000e+00;
    constexpr double k39 = 6.28318530717958623e+00;
    constexpr double k40 = 7.00000000000000000e+00;
    constexpr double k41 = 8.00000000000000000e+00;
    constexpr double k42 = 9.00000000000000000e+00;
    constexpr double k43 = 1.10000000000000000e+01;
    constexpr double k44 = 1.80540666735282009e+01;
    constexpr double k45 = 1.44432533388225608e+02;
    constexpr double k46 = 1.15546026710580486e+03;
    constexpr double k47 = 9.24368213684643888e+03;
