    SimdVector<double, 8> const one = broadcast<SimdVector<double, 8>>(k32);
    Vector3<SimdVector<double, 8>> x = distance;
    SimdVector<double, 8> const r2 = x.dot(x);
    SimdVector<double, 8> const y = broadcast<SimdVector<double, 8>>(k37) * r2;
    SimdVector<double, 8> const exponential = detail::ewaldExp(-y);
    SimdVector<double, 8> series = one;
    series = fma(series, y * broadcast<SimdVector<double, 8>>(k01), one);
    series = fma(series, y * broadcast<SimdVector<double, 8>>(k02), one);
    series = fma(series, y * broadcast<SimdVector<double, 8>>(k03), one);
    series = fma(series, y * broadcast<SimdVector<double, 8>>(k04), one);
    series = fma(series, y * broadcast<SimdVector<double, 8>>(k05), one);
    series = fma(series, y * broadcast<SimdVector<double, 8>>(k06), one);
    series = fma(series, y * broadcast<SimdVector<double, 8>>(k07), one);
    series = fma(series, y * broadcast<SimdVector<double, 8>>(k08), one);
    series = fma(series, y * broadcast<SimdVector<double, 8>>(k09), one);
    series = fma(series, y * broadcast<SimdVector<double, 8>>(k10), one);
    series = fma(series, y * broadcast<SimdVector<double, 8>>(k11), one);
    series = fma(series, y * broadcast<SimdVector<double, 8>>(k12), one);
    series = fma(series, y * broadcast<SimdVector<double, 8>>(k13), one);
    series = fma(series, y * broadcast<SimdVector<double, 8>>(k14), one);
    series = fma(series, y * broadcast<SimdVector<double, 8>>(k15), one);
    series = fma(series, y * broadcast<SimdVector<double, 8>>(k16), one);
    series = fma(series, y * broadcast<SimdVector<double, 8>>(k17), one);
